import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    cpu_data = []
    start_time = time.time()

    while time.time() - start_time < duration:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")

        if platform.system() == "Windows":
            output = subprocess.check_output('wmic cpu get loadpercentage', shell=True).decode()
            cpu_usage = output.split('\n')[1].strip()
        else:
            output = subprocess.check_output('top -bn1 | grep "Cpu(s)"', shell=True).decode()
            cpu_usage = output.split(',')[0].split(':')[1].strip().split('%')[0]

        cpu_data.append({
            "timestamp": timestamp,
            "cpu_usage": float(cpu_usage)
        })

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(cpu_data, f)
        return LOGFILE_PATH
    except IOError:
        return None

