import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []
    success = True

    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': 'Source folder does not exist',
            'failed_files': []
        }

    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)

    files = glob(os.path.join(src_folder, '*'))

    for file_path in files:
        if os.path.isfile(file_path):
            filename = os.path.basename(file_path)
            try:
                compressed_path = os.path.join(dst_folder, filename + '.gz')
                with open(file_path, 'rb') as f_in:
                    with open(compressed_path, 'wb') as f_out:
                        process = subprocess.Popen(['gzip', '-c'], stdin=f_in, stdout=f_out)
                        process.wait()
                        if process.returncode != 0:
                            raise Exception('gzip failed')
            except Exception as e:
                failed_files.append(filename)
                success = False

    if success:
        message = 'All files compressed and moved successfully'
    else:
        message = f'{len(failed_files)} file(s) failed to compress or move'

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

